from solution import reconcile
from itertools import product

invalid = [None, [], 'event', {}, {'entity':'','version':0,'payload':1}, {'entity':1,'version':0,'payload':1}, {'entity':'a','payload':1}, {'entity':'a','version':True,'payload':1}, {'entity':'a','version':-1,'payload':1}, {'entity':'a','version':1.0,'payload':1}, {'entity':'a','version':0,'deleted':0,'payload':1}, {'entity':'a','version':0,'deleted':None,'payload':1}, {'entity':'a','version':0}]
for event in invalid:
    for prefix in ([], [{'entity':'a','version':100,'payload':'winner'}]):
        try:
            reconcile(prefix + [event])
        except ValueError:
            pass
        else:
            raise AssertionError(('accepted invalid event',event))

# Exhaustively compare short streams to a simple independent sort-based oracle.
options = [{'entity':e,'version':v,'deleted':d,'payload':(e,v,d)}
           for e in ('a','A') for v in range(3) for d in (False,True)]
count = 0
for length in range(4):
    for stream in product(options, repeat=length):
        expected = {}
        for entity in ('a','A'):
            candidates = [(event['version'], i, event) for i,event in enumerate(stream) if event['entity']==entity]
            if candidates:
                winner = max(candidates, key=lambda item:item[:2])[2]
                if not winner['deleted']:
                    expected[entity] = winner['payload']
        assert reconcile(iter(stream)) == expected
        count += 1

for payload in (None, False, 0, '', [], {}):
    assert reconcile([{'entity':' ','version':0,'payload':payload}]) == {' ':payload}
payload = {'items': [[1]]}
events = [{'entity':'a','version':0,'payload':payload}]
result = reconcile(events)
assert events == [{'entity':'a','version':0,'payload':{'items':[[1]]}}]
payload['items'][0].append(2)
assert result == {'a':{'items':[[1]]}}
result['a']['items'].append([3])
assert payload == {'items':[[1,2]]}
assert reconcile([{'entity':'a','version':0,'deleted':True}]) == {}
class Uncopyable:
    def __deepcopy__(self, memo):
        raise AssertionError('stale payload copied')
assert reconcile([{'entity':'a','version':0,'payload':Uncopyable()}, {'entity':'a','version':1,'payload':2}]) == {'a':2}
print(f'PASS: 26 invalid-event cases; {count} exhaustive ordering streams; falsy/identifier, copy isolation, tombstone omission, and stale-copy checks')
